(async function(){'use strict';const client=KPSSAccount.client,gate=document.getElementById('accountGate');const text=(s)=>document.getElementById('gateMessage').textContent=s;
function loadScript(src){return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=()=>reject(Error('Çalışma alanı yüklenemedi.'));document.head.appendChild(s)})}
function exportData(data){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=u;a.download='kpss-kurtarma-yedegi.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
try{if(!client){text('Üyelik bağlantısı hazırlanıyor. Supabase yayımlanabilir anahtarı tanımlandıktan sonra giriş açılacak.');return}const {data:userData,error:userError}=await client.auth.getUser();if(userError||!userData.user){location.replace('./account.html');return}const user=userData.user,key='kpss-account-'+user.id,pendingKey=key+'-pending';const {data:row,error}=await client.from('kpss_user_data').select('payload,revision').eq('user_id',user.id).maybeSingle();if(error)throw Error('Hesap verileri açılamadı. Supabase veritabanı kurulumunu ve bağlantını kontrol et.');let revision=row?.revision??-1,snapshot=row?KPSS.validate(row.payload):KPSS.defaults(),pending;
try{pending=JSON.parse(localStorage.getItem(pendingKey))}catch{throw Error('Kaydedilmemiş yerel veriler okunamadı. Tarayıcı verilerini silmeden destek al.')}
if(pending){const local=KPSS.validate(pending.payload);if(pending.revision===revision)snapshot=local;else{ text('Bu cihazdaki kaydedilmemiş çalışmalarla başka cihazdaki kayıtlar farklı. Yerel yedeğini indirip buluttaki sürümü açabilirsin; sonra kayıtları karşılaştırarak içe aktar.');const button=document.createElement('button');button.textContent='Yerel yedeği indir ve buluttaki sürümü aç';button.onclick=()=>{exportData(local);localStorage.removeItem(pendingKey);location.reload()};gate.querySelector('div').appendChild(button);return}}
window.KPSS_ACCOUNT_KEY=key;localStorage.setItem(key,JSON.stringify(snapshot));let latest=null,running=false,blocked=false;
const status=s=>{const el=document.getElementById('cloudStatus');if(el)el.textContent=s};
async function flush(){if(running||blocked||!latest)return;running=true;while(latest&&!blocked){const payload=latest;latest=null;status('Hesabına kaydediliyor…');const result=await client.rpc('save_kpss_data',{p_payload:payload,p_expected:revision});if(result.error){latest=latest||payload;localStorage.setItem(pendingKey,JSON.stringify({payload:latest,revision}));blocked=String(result.error.message).includes('revision_conflict');status(blocked?'Başka cihazdaki kayıtlar değişti. Yedeğini indirip sayfayı yenile.':'Buluta kaydedilemedi. Bu cihazdaki taslağın korunuyor; yeniden dene.');break}revision=result.data;if(latest)localStorage.setItem(pendingKey,JSON.stringify({payload:latest,revision}));else{localStorage.removeItem(pendingKey);status('Hesabına kaydedildi.')}}running=false}
window.KPSSCloud={persist(payload){latest=structuredClone(payload);localStorage.setItem(pendingKey,JSON.stringify({payload:latest,revision}));void flush()},retry(){void flush()}};
await loadScript('./app.js');await loadScript('./controls.js');document.body.dataset.accountReady='true';gate.hidden=true;document.getElementById('memberEmail').textContent=user.email||'Hesabım';document.getElementById('retryCloud').onclick=()=>window.KPSSCloud.retry();document.getElementById('memberLogout').onclick=async()=>{if(localStorage.getItem(pendingKey)){window.showAction('Çıkıştan önce yedekle','Buluta henüz ulaşmamış kayıtların var. Yerel yedeğin indirilerek çıkış yapılacak.',async()=>{exportData(JSON.parse(localStorage.getItem(pendingKey)).payload);await client.auth.signOut();location.replace('./account.html')},'Yedekle ve çıkış yap')}else{await client.auth.signOut();location.replace('./account.html')}};
client.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT')location.replace('./account.html')});if(pending)window.KPSSCloud.persist(snapshot);else status('Hesabındaki kayıtlar açıldı.');
}catch(error){text(error.message||'Çalışma alanı açılamadı. Sayfayı yenileyip tekrar dene.')}
})();
